WITH cleaned AS (SELECT id, order_id, product_id, CASE WHEN quantity >= 7 THEN 'High' WHEN quantity >= 4 THEN 'Medium' ELSE 'Low' END AS quantity_level FROM order_items WHERE product_id IS NOT NULL), enriched AS (SELECT a.*, p.amount FROM cleaned a INNER JOIN orders p ON a.order_id = p.id), filtered AS (SELECT id, order_id, product_id, amount, ROUND(amount * 1.1, 2) AS adjusted_amount FROM enriched WHERE amount >= 810), latest AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY amount DESC, id) = 1), cleaned_order_items AS (SELECT id, order_id, product_id, adjusted_amount, CAST(adjusted_amount AS INT) AS adjusted_amount_int FROM latest WHERE product_id IS NOT NULL) SELECT *, LEAD(adjusted_amount, 1) OVER w_hist AS next_adjusted_amount, MIN(adjusted_amount) OVER (PARTITION BY product_id, order_id) AS product_id_min_adjusted_amount FROM cleaned_order_items WINDOW w_hist AS (ORDER BY adjusted_amount, id);
